  tft.drawString("Status", 12, 72, 2);
  tft.setTextColor(TFT_WHITE, TFT_BLACK);
  tft.drawString(status, 86, 72, 2);

  tft.setTextColor(TFT_GREEN, TFT_BLACK);
  tft.drawString("WiFi", 12, 98, 2);
  tft.setTextColor(TFT_WHITE, TFT_BLACK);
