void setup() {
  Serial.begin(115200);
  delay(500);
#if VORTEX_HAS_TFT
  tft.init();
  tft.setRotation(1);
#else
  Serial.println("[WARN] TFT_eSPI.h was not found at compile time. Install TFT_eSPI to enable the CYD screen.");
#endif
  drawUi("Booting", "offline", 0);

  Serial.println("\n=== Vortex CYD AI ===");
  bool sdReady = sd.init(SD_CS_PIN);
  String policy = sdReady ? sd.readFile(VortexConfig::configPath(), 4096) : VortexConfig::defaultConfig();
  String knowledge = sdReady ? sd.learnFromFiles(VortexConfig::knowledgeDir()) : "";
  llm.setPolicy(policy);
  llm.setKnowledgeBase(knowledge);

  String wifiText = sdReady ? sd.readFile("/vortex/wifi.txt", 512) : "";
  if (sdReady && !sd.fileExists("/vortex/wifi.txt")) {
    sd.writeFile("/vortex/wifi.txt", "ssid=YOUR_SSID\npassword=YOUR_PASSWORD\n");
  }
  String ssid = readWifiValue(wifiText, "ssid", FALLBACK_WIFI_SSID);
  String pass = readWifiValue(wifiText, "password", FALLBACK_WIFI_PASSWORD);
  wifi.connect(ssid, pass);

  int modelCount = sdReady ? sd.listModelFiles(VortexConfig::modelsDir()).size() : 0;
  drawUi(sdReady ? "SD learning ready" : "No SD card", wifi.getIP(), modelCount);

  String prompts[] = {"Hello, who are you?", "Who is your maker?", "How can you learn from files?", "Where do local models go?", "Explain artificial intelligence"};
  for (String prompt : prompts) {
    String answer = llm.generate(prompt, 64);
    Serial.println("Q: " + prompt);
    Serial.println("A: " + answer);
    if (sdReady) sd.appendFile("/vortex/ai_session.txt", "Q: " + prompt + "\nA: " + answer + "\n\n");
  }
}

void loop() {
  delay(10000);
  Serial.println("[Vortex] Running. " + wifi.getSignalStrength());
}

#include "wifi_manager.h"

WiFiManager::WiFiManager() {}

bool WiFiManager::connect(const String &ssid, const String &password) {
  if (ssid.length() == 0 || ssid == "YOUR_SSID") {
    Serial.println("[WiFi] No SSID configured. Edit /vortex/wifi.txt or firmware constants.");
    return false;
  }
  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid.c_str(), password.c_str());
  Serial.print("[WiFi] Connecting");
  for (uint8_t i = 0; i < 30 && WiFi.status() != WL_CONNECTED; ++i) {
    delay(500);
    Serial.print('.');
  }
  Serial.println();
  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("[WiFi] Connected: " + WiFi.localIP().toString());
    return true;
  }
  Serial.println("[WiFi] Connection failed; offline mode active.");
  return false;
}

bool WiFiManager::isConnected() { return WiFi.status() == WL_CONNECTED; }
void WiFiManager::disconnect() { WiFi.disconnect(true); }
String WiFiManager::getIP() { return isConnected() ? WiFi.localIP().toString() : "0.0.0.0"; }
String WiFiManager::getSignalStrength() { return isConnected() ? String(WiFi.RSSI()) + " dBm" : "offline"; }

HTTPClient_Vortex::HTTPClient_Vortex() {}

String HTTPClient_Vortex::buildWeatherURL(const String &city) {
  (void)city;
  return "http://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&current_weather=true";
}

String HTTPClient_Vortex::buildSearchURL(const String &query) {
  String encoded = query;
  encoded.replace(" ", "+");
  return "http://api.duckduckgo.com/?q=" + encoded + "&format=json&no_redirect=1";
}

String HTTPClient_Vortex::fetchWeather(const String &city) {
  if (WiFi.status() != WL_CONNECTED) return "Weather unavailable: WiFi offline.";
  http.begin(buildWeatherURL(city));
  int code = http.GET();
  String payload = code > 0 ? http.getString() : "Weather request failed.";
  http.end();
  return payload;
}

String HTTPClient_Vortex::webSearch(const String &query) {
  if (WiFi.status() != WL_CONNECTED) return "Search unavailable: WiFi offline.";
  http.begin(buildSearchURL(query));
  int code = http.GET();
  String payload = code > 0 ? http.getString() : "Search request failed.";
  http.end();
  return payload;
}

String HTTPClient_Vortex::checkForUpdate(const String &updateURL) {
  if (WiFi.status() != WL_CONNECTED) return "Update check unavailable: WiFi offline.";
  http.begin(updateURL);
  int code = http.GET();
  String payload = code > 0 ? http.getString() : "Update check failed.";
  http.end();
  return payload;
}

